const PHOTO=[['09_Collection/meisyo_01.png','宫津市','京都府北部','海湾沙洲','海风从两侧的蓝色水面吹来，细长的绿洲像一条通往远方的小路。妙脆角喵在山坡上坐了很久，才舍得收起这片风景。'],['09_Collection/meisyo_02.png','屋久岛町','鹿儿岛县','森林古树','潮湿的森林里，一棵古树安静地撑起浓雾和绿荫。妙脆角喵绕着树根走了一圈，觉得自己的脚步忽然变得很轻。'],['09_Collection/meisyo_03.png','海风町','北方海岸','草原灯塔','黑白相间的灯塔立在海风里，为远处的船守着方向。妙脆角喵在草坡上眯起眼睛，记住了光照向海面的样子。'],['09_Collection/meisyo_04.png','汤烟市','山谷温泉乡','山崖吊篮','竹篮从陡峭的山崖边缓缓升起，下面是被雾气染成浅蓝色的山谷。妙脆角喵没有急着靠近，只在安全的石头后认真看了看。'],['09_Collection/meisyo_05.png','屋久岛町','苔木森林','绿苔倒木','倒下的巨木成了蕨类和青苔的新家。妙脆角喵沿着木纹慢慢走，发现结束有时也是另一段生长的开始。'],['09_Collection/meisyo_06.png','青空市','纪念公园','铜色纪念塔','铜色高塔在晴空下闪着温暖的光，顶端像一颗圆圆的种子。妙脆角喵仰头看了好一会儿，把它画进了旅行手账。'],['09_Collection/meisyo_07.png','汤之町','高原温泉区','露天汤池','一座座露天汤池冒着白雾，热水沿着石槽慢慢流动。妙脆角喵在木板路边暖了暖脚，觉得长途旅行的疲惫都散开了。'],['09_Collection/meisyo_08.png','白鹭市','城下町','青瓦古城','层层青瓦在晴空下展开，白色城墙像云一样明亮。妙脆角喵从石坡下仰望，把屋檐的弧线一笔一笔记进手账。'],['09_Collection/meisyo_09.png','汤烟町','山腰温泉区','翡翠汤瀑','浅绿色温泉从石壁上缓缓流下，水汽绕着黑色石灯。妙脆角喵隔着竹栏听水声，猜想这里到了冬天一定更温暖。'],['09_Collection/meisyo_10.png','长野市','山门古道','古寺山门','宽阔石道一直通向庄严山门，松树在两旁轻轻摇动。妙脆角喵跟着参拜的人慢慢向前，在门前安静地停了一会儿。']];
const PHOTO_CHINA=[['09_Collection/china_01.png','桂林市','广西壮族自治区','漓江山水','青绿的漓江从层叠峰林间缓缓穿过，远山像淡墨一样铺向天边。妙脆角喵沿着河岸走走停停，把水面最亮的一段收进了相册。'],['09_Collection/china_02.png','张家界市','湖南省','峰林古木','古树撑开浓密树冠，薄雾在砂岩峰柱之间轻轻游动。妙脆角喵靠着宽大的树根歇脚，听见森林深处传来清脆鸟鸣。'],['09_Collection/china_03.png','青岛市','山东省','海岸灯塔','红白相间的灯塔立在青草覆盖的海岬上，晴空和海面连成明亮的蓝色。妙脆角喵迎着海风眯起眼睛，记下了回航的方向。'],['09_Collection/china_04.png','重庆市','渝中区','长江索道','红色索道车从山城楼宇之间越过宽阔江面，远近山坡层层展开。妙脆角喵贴着窗边向下看，觉得整座城市正在脚下慢慢移动。'],['09_Collection/china_05.png','九寨沟县','四川省','碧湖森林','清澈碧湖倒映着针叶林，倒木和圆石安静地躺在浅水边。妙脆角喵沿湖走了一圈，连脚步都不自觉地放轻了。'],['09_Collection/china_06.png','西安市','陕西省','大雁塔','层层塔檐在蓝天下稳稳向上，古塔四周的松柏带着安静的绿意。妙脆角喵仰头数完塔层，又在手账里认真画了一遍。'],['09_Collection/china_07.png','泸定县','四川省','雪山温泉','雪峰映着温润天光，山脚的汤池升起一缕缕白雾。妙脆角喵在池边暖了暖爪子，长途跋涉的疲惫也慢慢散开。'],['09_Collection/china_08.png','北京市','怀柔区','山岭长城','长城沿着起伏山脊蜿蜒远去，一座座敌楼连接着青绿群山。妙脆角喵登上高处回望，发现来时的路已经变成细细一线。'],['09_Collection/china_09.png','松潘县','四川省','黄龙彩池','一层层彩池顺着山坡铺开，碧绿与浅蓝在金色池沿之间流动。妙脆角喵蹲在木道边看了很久，舍不得惊动水里的倒影。'],['09_Collection/china_10.png','杭州市','浙江省','灵隐山门','青瓦山门藏在苍翠山林之间，石路从树影下安静地延伸过去。妙脆角喵在门前停下脚步，听了一会儿风吹松叶的声音。']];
