function restoreClovers(amount){s.harvestedClovers=s.harvestedClovers||[];while(amount-->0&&s.harvestedClovers.length)s.harvestedClovers.pop();s.garden=GARDEN_CAPACITY-s.harvestedClovers.length}function grow(){let n=Math.floor((Date.now()-s.gardenAt)/60000);if(n&&s.garden<GARDEN_CAPACITY){restoreClovers(n);s.gardenAt=Date.now();save()}}
function periodKey(){return ['morning','afternoon','evening'][s.timePhase||0]}function periodLabel(){return {morning:'早晨',afternoon:'午后',evening:'傍晚'}[periodKey()]}function activePhotos(){return PHOTO_BY_REGION[s.albumRegion]||PHOTO_CHINA}function renderCropSetting(){let theme=resourceTheme();$$('[data-crop-type]').forEach(button=>{let selected=button.dataset.cropType===s.cropType;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected))});$$('[data-resource-icon]').forEach(image=>{image.src=theme.icon;image.alt=theme.name});$('#cropStatus').textContent=`当前${theme.name}：${resourceAmount()} ${theme.unit}`}function renderSoilSetting(){$$('[data-soil-type]').forEach(button=>{let selected=button.dataset.soilType===s.soilType;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected))});$('#soilStatus').textContent=`当前：${s.soilType==='old'?'旧泥土':'新泥土'}`}function selectSoilType(type){if(!['old','new'].includes(type)||type===s.soilType)return;s.soilType=type;s.placements.garden=s.placements.garden.filter(item=>!isSoilLike(item.type));if(currentPlacement()&&isSoilLike(currentPlacement().type))selectedPlacementId=null;save();renderObjectPalette();render();toast(`已切换为${type==='old'?'旧泥土':'新泥土'}，原泥土已删除`)}function render(){grow();$('#money').textContent=resourceAmount();$('#dayText').textContent=`第 ${s.day} 天`;$('#clockText').textContent=periodLabel();$('#testTimeStatus').textContent=`第 ${s.day} 天 · ${periodLabel()}`;renderWorld();renderPlacements();renderTasks();renderBag();renderShop();renderMail();renderAlbum();renderVisitor();renderCharacters();renderTaskTravelDock();renderCropSetting();renderSoilSetting();$('#soundToggle b').textContent=s.sound?'开启':'关闭';$('#albumRegionToggle b').textContent=ALBUM_REGION_LABEL[s.albumRegion]}

