function renderWorld(){let garden=s.scene==='garden',period=periodKey(),picked=new Set(s.harvestedClovers||[]),catfish=s.cropType==='catfish',field=$('#cloverField');$('#world').classList.toggle('garden-scene',garden);$('#world').classList.remove('time-morning','time-afternoon','time-evening');$('#world').classList.add(`time-${period}`);$('#worldBg').src=garden?CAT_SCENES.garden:CAT_SCENES.home;$('#candleLight').classList.toggle('hidden',garden||period!=='evening');if(!mealPlaying)$('#frogActor').className='actor frog-actor sprite '+(garden?'garden-frog':'home-chair');$('#frogActor').classList.toggle('hidden',s.trip);$('#visitorActor').classList.toggle('hidden',!garden);field.classList.toggle('hidden',!garden);field.classList.toggle('catfish-mode',catfish);field.setAttribute('aria-label',catfish?'猫草鱼田':'三叶草田');$('#mealTable')?.classList.toggle('hidden',garden||s.trip||mealPlaying);$$('#cloverField button').forEach(b=>{b.classList.toggle('picked',picked.has(+b.dataset.cloverId));b.setAttribute('aria-label',catfish?'收获猫草鱼主粮':b.classList.contains('clover-rare')?'收获四叶草':'收获三叶草')});$('.desk').classList.toggle('hidden',garden);let legacyBag=$('.bag');if(legacyBag)legacyBag.classList.toggle('hidden',garden);$('#homeDockButton').classList.toggle('hidden',!garden);$('#gardenDockButton').classList.toggle('hidden',garden);$('#panLeft').classList.toggle('hidden',!garden);$('#panRight').classList.toggle('hidden',!garden);$('#dragHint').classList.toggle('hidden',!garden);if(garden)applyGardenPan();$('#harvestDot').classList.toggle('on',!!s.garden);$('#photoDot').classList.toggle('on',s.newPhoto);if(frogTalkPage<0)$('#bubble').textContent=garden?(s.garden?(catfish?'猫草鱼成熟了，收好就是旅行主粮。':'三叶草长好了，点一点就能收获。'):'风吹过空空的草地，过一会儿再来吧。'):s.trip?'妙脆角喵正在旅行。你完成专注，它会更快回来。':tick?'妙脆角喵正在安静地陪你。':s.tasks.length?'打开任务本，推进今天的一小步吧。':'先在任务本里写下今天要做的事。'}

